#include <vector>
using namespace std;

class Solution {
public:
    int wateringPlants(vector<int>& plants, int capacity) {
        int steps = 0, curr = capacity;
        for (int i = 0; i < plants.size(); ++i) {
            if (curr < plants[i]) {
                steps += 2 * i;
                curr = capacity;
            }
            curr -= plants[i];
            steps++;
        }
        return steps;
    }
};
